@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if n.begins_with(".") == false:
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk("assets/quaternius", files)
	var gltf_low: Array = []
	var gltf_count := 0
	var dirs: Array = []
	for f in files:
		var fs := String(f)
		if fs.get_extension() == "gltf":
			gltf_count += 1
			var txt: String = FileAccess.get_file_as_string("res://" + fs)
			if txt.find("textures/") != -1:
				gltf_low.append(fs)
				if gltf_low.size() <= 25:
					dirs.append(fs)
	var rep := {"gltf_total": gltf_count, "gltf_with_lowercase_textures_ref": gltf_low.size(), "samples": dirs}
	var out := FileAccess.open("res://tools/gc_case_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "CASE gltf=" + str(gltf_count) + " lowref=" + str(gltf_low.size())
